import 'dart:math';

/// Bir soru. [options] içinde ilk seçenek her zaman doğru cevaptır;
/// oyun sırasında seçenekler karıştırılır.
class Question {
  const Question(this.text, this.options, {this.difficulty = 5});

  final String text;
  final List<String> options;

  /// Sorunun zorluk derecesi (1: Başlangıç .. 10: Efsane).
  final int difficulty;

  String get answer => options.first;

  String get difficultyLabel => switch (difficulty) {
        <= 3 => 'Kolay',
        <= 5 => 'Orta',
        <= 7 => 'Zor',
        <= 9 => 'Uzman',
        _ => 'Efsane',
      };

  /// Seçenekleri karıştırılmış kopyası ve doğru cevabın yeni sırası.
  (List<String>, int) shuffled(Random rng) {
    final list = [...options]..shuffle(rng);
    return (list, list.indexOf(answer));
  }
}

enum PvpCategory {
  benKimim('Ben Kimim?'),
  championsLeague('Champions League'),
  hangiTakim('Hangi Takım?');

  const PvpCategory(this.title);

  final String title;
}

List<Question> pickQuestions(List<Question> pool, int count, Random rng) =>
    ([...pool]..shuffle(rng)).take(count).toList();

/// Tek oyunculu modda her seviyenin (1..10) kendine ait ayrık soru dilimi vardır
/// (ör. 80 soruluk bölümde seviye başına 8 soru); bu dilim içinden [count] tanesi
/// rastgele seçilir. Böylece hem seviyeler arasında soru tekrarı olmaz hem de
/// aynı seviye tekrar oynandığında farklı soru kombinasyonları gelir.
List<Question> pickLevelQuestions(int chapter, int level, int count, Random rng) {
  final pool = chapterPool(chapter);
  final sliceSize = max(count, pool.length ~/ 10);
  final start = ((level - 1) * sliceSize) % pool.length;
  final slice = <Question>[];
  for (var i = 0; i < sliceSize; i++) {
    slice.add(pool[(start + i) % pool.length]);
  }
  slice.shuffle(rng);
  final picked = slice.take(count).toList();
  // Seçilen 5 soruyu kendi içinde kolaydan zora doğru sırala (kademeli zorlaşan akış).
  picked.sort((a, b) => a.difficulty.compareTo(b.difficulty));
  return picked;
}

/// Online PVP modunda iki oyuncunun birebir aynı soruları aynı sırada görmesi için
/// ortak [seed] ile deterministik seçim yapar.
List<Question> pickSeededPvpQuestions(PvpCategory category, int count, int seed) {
  final rng = Random(seed);
  return pickQuestions(pvpPool(category), count, rng);
}

List<Question> chapterPool(int chapter) => switch (chapter) {
      1 => chapter1,
      2 => chapter2,
      3 => chapter3,
      _ => chapter4,
    };

List<Question> pvpPool(PvpCategory c) => switch (c) {
      PvpCategory.benKimim => benKimim,
      PvpCategory.championsLeague => championsLeague,
      PvpCategory.hangiTakim => hangiTakim,
    };

